import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.Dkj3JE0_.js";const p=JSON.parse('{"title":"JLPT N2 Plan","description":"","frontmatter":{"title":"JLPT N2 Plan"},"headers":[],"relativePath":"blogs/JLPT-N2/plan.md","filePath":"blogs/JLPT-N2/plan.md"}'),o={name:"blogs/JLPT-N2/plan.md"};function i(s,t,l,d,h,c){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="jlpt-n2-learning-plan" tabindex="-1">JLPT N2 Learning Plan <a class="header-anchor" href="#jlpt-n2-learning-plan" aria-label="Permalink to &quot;JLPT N2 Learning Plan&quot;">​</a></h1><blockquote><p><strong>Working assumption:</strong> exam on <strong>Sunday 6 December 2026</strong>. Intensive coverage <strong>13 October → Friday 14 November</strong> (soft close <strong>16 November</strong>) at a hard cap of <strong>2.0 hours per day</strong> (~<strong>14 hours per week</strong>). <strong>1–5 December</strong> is buffer only (≤1 hour review); <strong>no new first-pass</strong> in December. Do not expand into a heavier December ramp.</p></blockquote><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><ul><li>Clear the remaining vocabulary queue (~<strong>2000</strong> items at ~<strong>60 per day</strong>) and remaining video lessons (~<strong>180</strong> at ~<strong>5–6 per day</strong>) by mid-November.</li><li>Keep grammar notes, example sentences, and miss-driven flashcards current with Caligo support — recognition in context, not cards alone.</li><li>Rotate evening practice across grammar, exam practice, reading, and listening so no skill goes dark for a full week.</li><li>Enter December with first-pass complete; use Dec 1–5 only for light review and logistics before the 6 December exam.</li></ul><h2 id="current-focus-as-of-14-oct-2026" tabindex="-1">Current focus (as of 14 Oct 2026) <a class="header-anchor" href="#current-focus-as-of-14-oct-2026" aria-label="Permalink to &quot;Current focus (as of 14 Oct 2026)&quot;">​</a></h2><p><strong>Today:</strong> vocabulary app session in the morning slot.</p><p><strong>Tracks in flight</strong></p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Remaining (approx.)</th><th style="text-align:right;">Daily pace</th></tr></thead><tbody><tr><td>Vocabulary (app)</td><td style="text-align:right;">~2000</td><td style="text-align:right;">~60 / day</td></tr><tr><td>Video lessons</td><td style="text-align:right;">~180</td><td style="text-align:right;">~5–6 / day</td></tr><tr><td>Grammar / notes / cards</td><td style="text-align:right;">Ongoing with Caligo</td><td style="text-align:right;">Mon &amp; Wed evening</td></tr><tr><td>Practice / reading / listening</td><td style="text-align:right;">Rotate evenings</td><td style="text-align:right;">See rhythm below</td></tr></tbody></table><p>Grammar and video deep-work with Caligo follow when the vocabulary block is done for the day — tap Caligo to start those parts; do not invent a heavier evening load.</p><h2 id="daily-rhythm-hard-cap-2-0-h" tabindex="-1">Daily rhythm (hard cap 2.0 h) <a class="header-anchor" href="#daily-rhythm-hard-cap-2-0-h" aria-label="Permalink to &quot;Daily rhythm (hard cap 2.0 h)&quot;">​</a></h2><p>Slots must not overlap CFA (20:00–02:00), workout (18:00–20:00), or the Monday weekly-report block (08:00–10:00).</p><table tabindex="0"><thead><tr><th>Slot</th><th style="text-align:right;">Time</th><th>Work</th></tr></thead><tbody><tr><td>Morning vocab</td><td style="text-align:right;">06:45–07:15</td><td>App vocabulary (~60 items).</td></tr><tr><td>Morning video</td><td style="text-align:right;">07:15–08:05</td><td>Video lessons (~5–6).</td></tr><tr><td>Evening rotate</td><td style="text-align:right;">21:00–21:40</td><td>Skill of the day (table below).</td></tr></tbody></table><h3 id="evening-rotation-21-00–21-40" tabindex="-1">Evening rotation (21:00–21:40) <a class="header-anchor" href="#evening-rotation-21-00–21-40" aria-label="Permalink to &quot;Evening rotation (21:00–21:40)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Day</th><th>Focus</th></tr></thead><tbody><tr><td>Mon</td><td>Grammar · notes / cards (Caligo)</td></tr><tr><td>Tue</td><td>Practice (exam-style sets)</td></tr><tr><td>Wed</td><td>Grammar · notes / cards (Caligo)</td></tr><tr><td>Thu</td><td>Reading</td></tr><tr><td>Fri</td><td>Listening</td></tr><tr><td>Sat</td><td>Practice (exam-style sets)</td></tr><tr><td>Sun</td><td>Listening</td></tr></tbody></table><h2 id="intensive-roadmap" tabindex="-1">Intensive roadmap <a class="header-anchor" href="#intensive-roadmap" aria-label="Permalink to &quot;Intensive roadmap&quot;">​</a></h2><h3 id="phase-a-—-coverage-13-oct-→-fri-14-nov" tabindex="-1">Phase A — Coverage (13 Oct → Fri 14 Nov) <a class="header-anchor" href="#phase-a-—-coverage-13-oct-→-fri-14-nov" aria-label="Permalink to &quot;Phase A — Coverage (13 Oct → Fri 14 Nov)&quot;">​</a></h3><ul><li>Hold the <strong>2.0 h/day</strong> cap; missed morning time does not spill into the CFA evening block.</li><li>Vocabulary and video run every day at the rates above until queues clear.</li><li>Grammar evenings: contrast patterns, short example sentences, and miss-driven flashcards — not a second textbook.</li><li>Practice / reading / listening evenings: timed or one-pass work; log misses for the next grammar or card session.</li></ul><p><strong>Soft close: 16 November</strong> — finish any leftover first-pass items; stop opening new grammar chapters or video series after that.</p><h3 id="phase-b-—-buffer-1–5-dec" tabindex="-1">Phase B — Buffer (1–5 Dec) <a class="header-anchor" href="#phase-b-—-buffer-1–5-dec" aria-label="Permalink to &quot;Phase B — Buffer (1–5 Dec)&quot;">​</a></h3><ul><li>≤<strong>1 hour per day</strong> review only.</li><li>High-confusion grammar pairs, weak listening cues, and recurring vocab misses.</li><li>Confirm exam logistics; protect sleep.</li><li><strong>No new first-pass material.</strong></li></ul><h3 id="exam-day-—-sun-6-dec" tabindex="-1">Exam day — Sun 6 Dec <a class="header-anchor" href="#exam-day-—-sun-6-dec" aria-label="Permalink to &quot;Exam day — Sun 6 Dec&quot;">​</a></h3><ul><li>Light warm-up only if useful; no cramming.</li></ul><h2 id="weekly-check-optional-sunday-note" tabindex="-1">Weekly check (optional Sunday note) <a class="header-anchor" href="#weekly-check-optional-sunday-note" aria-label="Permalink to &quot;Weekly check (optional Sunday note)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>Vocab done / remaining:</span></span>
<span class="line"><span>Videos done / remaining:</span></span>
<span class="line"><span>Evening slots hit (grammar / practice / reading / listening):</span></span>
<span class="line"><span>One pattern or passage that still feels fragile:</span></span>
<span class="line"><span>Adjust pace next week? (stay at cap — do not add hours)</span></span></code></pre></div><h2 id="next-seven-days-14–20-oct" tabindex="-1">Next seven days (14–20 Oct) <a class="header-anchor" href="#next-seven-days-14–20-oct" aria-label="Permalink to &quot;Next seven days (14–20 Oct)&quot;">​</a></h2><ul><li>[ ] Keep morning vocab (06:45–07:15) and video (07:15–08:05) every day.</li><li>[ ] Mon 14 / Wed 16 evening: grammar with Caligo when tapped — notes and example cards, not a longer session.</li><li>[ ] Tue 15 / Sat 18 evening: practice sets; log misses.</li><li>[ ] Thu 17 evening: reading; Fri 18 / Sun 20 evening: listening.</li><li>[ ] Stay inside the 2.0 h/day cap; do not borrow from the CFA night block.</li><li>[ ] Do not plan a December first-pass ramp.</li></ul>`,26)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
